import pandas as pd
import numpy as np

def quality_counts_fixed(df: pd.DataFrame) -> dict:
    missing = int(((df["reading"].isna()) | (df["baseline"].isna())).sum())
    undefined = int(((df["reading"] == 0) & (df["baseline"] == 0)).sum())
    return {"missing": missing, "undefined_ratio": undefined}

test_cases = [
    {
        "name": "missing",
        "df": pd.DataFrame({
            "reading": pd.Series([1.0, np.nan, 2.0], dtype="Float64"),
            "baseline": pd.Series([1.0, 1.0, np.nan], dtype="Float64")
        }),
        "expected": {"missing": 2, "undefined_ratio": 0}
    },
    {
        "name": "undefined",
        "df": pd.DataFrame({
            "reading": pd.Series([0.0, 1.0], dtype="Float64"),
            "baseline": pd.Series([0.0, 1.0], dtype="Float64")
        }),
        "expected": {"missing": 0, "undefined_ratio": 1}
    },
    {
        "name": "both",
        "df": pd.DataFrame({
            "reading": pd.Series([np.nan, 0.0, 1.0], dtype="Float64"),
            "baseline": pd.Series([1.0, 0.0, np.nan], dtype="Float64")
        }),
        "expected": {"missing": 2, "undefined_ratio": 1}
    },
    {
        "name": "mixed_na_zero",
        "df": pd.DataFrame({
            "reading": pd.Series([np.nan, 0.0, np.nan], dtype="Float64"),
            "baseline": pd.Series([0.0, np.nan, 0.0], dtype="Float64")
        }),
        "expected": {"missing": 3, "undefined_ratio": 0}
    }
]

for case in test_cases:
    result = quality_counts_fixed(case["df"])
    print(f"{case['name']}: {result} == {case['expected']} -> {result == case['expected']}")
